import sys

def solve_binary_maximize(binary_str):
    # Find the first '0' that comes after a '1'
    first_zero_after_one = -1
    for i, ch in enumerate(binary_str):
        if ch == '1':
            # Mark this position as a '1'
            pass
        elif ch == '0' and first_zero_after_one == -1:
            # Found the first '0' after a '1'
            first_zero_after_one = i

    # If we found a '0' after a '1', delete it
    if first_zero_after_one != -1:
        return binary_str[:first_zero_after_one] + binary_str[first_zero_after_one+1:]

    # If no '0' after a '1', delete the last character (which must be a '1')
    return binary_str[:-1]

if __name__ == "__main__":
    binary_str = sys.stdin.read().strip()
    result = solve_binary_maximize(binary_str)
    print(result)
"}

