    """Check if s is a subsequence of t."""
    it = iter(t)
    return all(char in it for char in s)

def solve():
    s = input().strip()
    t = input().strip()

    count = 0

    # Find all positions where t[0:i] contains s as a subsequence
    # and t[i:] also contains s as a subsequence
    for i in range(1, len(t)):
        left = t[:i]
        right = t[i:]
        if is_subsequence(s, left) and is_subsequence(s, right):
            count += 1

    print(count)

solve()
