import sys

def is_valid_username(s):
    """Check if s is a valid username."""
    if not 1 <= len(s) <= 16:
        return False
    if '.' in s:
        return False
    if not s.isalnum() and '_' not in s:
        return False
    return True

def is_valid_hostname(s):
    """Check if s is a valid hostname."""
    if not 1 <= len(s) <= 32:
        return False
    words = s.split('.')
    if len(words) == 0:
        return False
    for word in words:
        if not 1 <= len(word) <= 16:
            return False
        if not word.isalnum() and '_' not in word:
            return False
    return True

def is_valid_resource(s):
    """Check if s is a valid resource."""
    if not 1 <= len(s) <= 16:
        return False
    if not s.isalnum() and '_' not in s:
        return False
    return True

def is_valid_jabber_id(s):
    """Check if s is a valid Jabber ID."""
    if s.count('@') != 1:
        return False
    parts = s.split('@', 1)
    username = parts[0]
    rest = parts[1]

    if not is_valid_username(username):
        return False

    if rest.count('/') != 1 and rest.count('/') != 0:
        return False

    if rest.count('/') == 1:
        host_parts = rest.split('/', 1)
        hostname = host_parts[0]
        resource = host_parts[1]

        if not is_valid_hostname(hostname):
            return False

        if not is_valid_resource(resource):
            return False
    else:
        hostname = rest
        resource = ''

        if not is_valid_hostname(hostname):
            return False

    return True

line = sys.stdin.readline().strip()
if is_valid_jabber_id(line):
    print("YES")
else:
    print("NO")
