import sys
from collections import defaultdict

def count_occurrences(text, pattern):
    """Count occurrences of pattern in text using KMP algorithm"""
    def kmp_failure(pattern):
        fail = [0] * len(pattern)
        j = 0
        for i in range(1, len(pattern)):
            while j > 0 and pattern[i] != pattern[j]:
                j = fail[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                fail[i] = j
            else:
                fail[i] = 0
        return fail

    fail = kmp_failure(pattern)
    j = 0
    count = 0
    for i, char in enumerate(text):
        while j > 0 and char != pattern[j]:
            j = fail[j - 1]
        if char == pattern[j]:
            j += 1
            if j == len(pattern):
                count += 1
                j = fail[j - 1]
    return count

def solve():
    data = sys.stdin.read().strip().split('\n')
    t = data[0]
    n = int(data[1])
    strings = data[2:2+n]

    # Find all occurrences of each string in t
    occurrences = defaultdict(list)
    for i, s in enumerate(strings):
        # Find all start positions of s in t
        start_positions = []
        pos = 0
        while True:
            pos = t.find(s, pos)
            if pos == -1:
                break
            start_positions.append(pos)
            pos += 1  # Move past this occurrence to find overlapping ones

        occurrences[i] = start_positions

    # For each occurrence of a string, count how many occurrences of other strings start immediately after
    result = 0
    for i, start_positions in occurrences.items():
        len_i = len(strings[i])
        for pos in start_positions:
            end_pos = pos + len_i
            # Count how many occurrences of any string start at end_pos
            for j in range(n):
                if end_pos < len(t) - len(strings[j]) + 1:
                    # Check if string j starts at end_pos
                    if t[end_pos:end_pos+len(strings[j])] == strings[j]:
                        result += 1

    print(result)

if __name__ == "__main__":
    solve()
"}

