import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Initialize multiset with initial elements
    freq = {}
    for _ in range(n):
        val = int(next(it))
        freq[val] = freq.get(val, 0) + 1

    # Fenwick Tree to maintain counts
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    # Maximum possible value is n
    ft = FenwickTree(n)
    for val in freq:
        ft.update(val, freq[val])

    for _ in range(q):
        k = int(next(it))
        if k > 0:
            # Add k to the multiset
            ft.update(k, 1)
            freq[k] = freq.get(k, 0) + 1
        else:
            # Remove the |k|-th order statistic
            target_k = -k

            # Binary search to find the smallest value with prefix sum >= target_k
            low = 1
            high = n
            ans = -1
            while low <= high:
                mid = (low + high) // 2
                cnt = ft.query(mid)
                if cnt >= target_k:
                    ans = mid
                    high = mid - 1
                else:
                    low = mid + 1

            if ans == -1:
                # This shouldn't happen as per problem guarantees
                continue

            # Remove one occurrence of ans
            ft.update(ans, -1)
            freq[ans] -= 1
            if freq[ans] == 0:
                del freq[ans]

    if not freq:
        print(0)
    else:
        # Output any element from the multiset
        print(next(iter(freq)))

if __name__ == "__main__":
    solve()
"}

