def count_occurrences(t, s):
    """Count the number of occurrences of substring s in string t"""
    if len(s) > len(t):
        return 0

    # Use a sliding window approach
    count = 0
    for i in range(len(t) - len(s) + 1):
        if t[i:i+len(s)] == s:
