            if not last_used or (last_used.get(s[i], i) >= i and s[last_used[s[i]]] != s[i]):
                # Check if there's an uppercase letter between the position of the last used letter and current
                if not last_used:
                    # No letter used, we can use this one
                    used_letters.add(s[i])
                    last_used = {s[i]: i}
                    max_count = 1
                else:
                    # Check between position of s[i] and s[last letter] (which is also s[i]?)
                    has_upper_between = False
                    start_pos = last_used[s[i]]
                    end_pos = i
                    for k in range(start_pos + 1, end_pos):
