def solve():
    n, m, k = map(int, sys.stdin.readline().split())

    # Try the optimal split where h and v are as equal as possible
    # This means h = min(k//2, n-1), v = k - h
    h1 = min(k // 2, n - 1)
    v1 = k - h1
    if v1 <= m - 1:
        area1 = n // (h1 + 1) * m // (v1 + 1)
    else:
        area1 = -1

    # Try another nearby split if the first is invalid
    h2 = min((k + 1) // 2, n - 1)
    v2 = k - h2
    if v2 <= m - 1:
        area2 = n // (h2 + 1) * m // (v2 + 1)
    else:
        area2 = -1

    # Try making all cuts horizontal
    if k <= n - 1:
        area3 = n // (k + 1) * m
    else:
        area3 = -1

    # Try making all cuts vertical
    if k <= m - 1:
        area4 = n * m // (k + 1)
    else:
        area4 = -1

    # Find the maximum valid area
    max_area = max([area for area in [area1, area2, area3, area4] if area != -1])

    print(max_area)

