    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # The maximum possible GCD is the largest divisor of the elements
    # such that for each element, we can decrease it to a multiple of that divisor

    max_gcd = 1

    # Try each element as a potential GCD
    for i in range(n):
        candidate = a[i]

        # Check if we can set all other elements to multiples of candidate
        possible = True
        for j in range(n):
            aj = a[j]
            # We can set aj to any value in [aj - k, aj]
            # We need at least one multiple of candidate in that range
            has_multiple = False
            for multiple in range(candidate, aj + 1, candidate):
                if aj - multiple <= k:
                    has_multiple = True
                    break
            if not has_multiple:
                possible = False
                break

        if possible:
            max_gcd = max(max_gcd, candidate)

