                    dist += 1
                push_right[x][y] = dist

    # Precompute how far we can push a rock down from each cell
    push_down = [[0] * m for _ in range(n)]
    for x in range(n):
        for y in range(m):
            if grid[x][y] == 'R':
                # Find how far we can push down
                dist = 0
                for k in range(1, n - x):
                    if grid[x + k][y] == 'R':
                        break
                    dist += 1
                push_down[x][y] = dist

