import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    # flights: (day, from, to, cost)
    flights = []
    for _ in range(m):
        d = int(next(it))
        f = int(next(it))
        t = int(next(it))
        c = int(next(it))
        flights.append((d, f, t, c))

    # For each city, find minimum arrival cost by day
    # arrival_cost[city][d] = minimum cost to arrive in Metropolis by day d
    INF = 10**18
    arrival_cost = [ [INF] * (2 * k + 1) for _ in range(n + 1) ]

    # For each city, find minimum departure cost from day
    departure_cost = [ [INF] * (2 * k + 1) for _ in range(n + 1) ]

    # Initialize: city 0 is Metropolis, so no cost
    for city in range(n + 1):
        arrival_cost[city][0] = 0
        departure_cost[city][0] = 0

    # Update costs for each flight
    for d, f, t, c in flights:
        # If flight is going to Metropolis (city 0)
        if t == 0:
            # This is an arrival flight
            for city in range(1, n + 1):
                arrival_cost[city][d] = min(arrival_cost[city][d], c)
        # If flight is going from Metropolis (city 0)
        elif f == 0:
            # This is a departure flight
            for city in range(1, n + 1):
                departure_cost[city][d] = min(departure_cost[city][d], c)

    # Propagate minimum costs forward for arrival
    for city in range(1, n + 1):
        for i in range(1, 2 * k + 1):
            arrival_cost[city][i] = min(arrival_cost[city][i], arrival_cost[city][i - 1])

    # Propagate minimum costs forward for departure
    for city in range(1, n + 1):
        for i in range(1, 2 * k + 1):
            departure_cost[city][i] = min(departure_cost[city][i], departure_cost[city][i - 1])

    # Now find the minimum total cost
    min_total_cost = INF

    # We need to gather everyone for k days
    # We can gather starting on day d (1-indexed?)
    # Actually, we need to bring them all to Metropolis by some day, then they stay for k days
    # So for each day d from 1 to k, we bring them by day d and send them back on or after day d+k

    for d in range(1, k + 1):
        # Bring everyone by day d
        can_arrive = True
        for city in range(1, n + 1):
            if arrival_cost[city][d] >= INF:
                can_arrive = False
                break
        if not can_arrive:
            continue

        # Send everyone back on or after day d+k
        can_depart = True
        for city in range(1, n + 1):
            if departure_cost[city][d + k] >= INF:
                can_depart = False
                break
        if not can_depart:
            continue

        total = sum(arrival_cost[city][d] + departure_cost[city][d + k] for city in range(1, n + 1))
        min_total_cost = min(min_total_cost, total)

    if min_total_cost == INF:
        print(-1)
    else:
        print(min_total_cost)

