queue = []  # will store (ti, di, index)

results = [-1] * n

i = 0
while i < n or queue:
    if i < n:
        ti, di, idx = queries[i]
        if server_free <= ti:
            # Server is free at or before ti
            if queue:
                # Process queue if queue has queries that arrived before or at ti
                while queue and server_free <= queue[0][0]:
                    tiq, diq, idxq = queue.pop(0)
                    server_free += diq
                    results[idxq] = server_free
            # Now process this query if queue is empty
            if not queue:
                server_free = ti + di
                results[idx] = server_free
            i += 1
        else:
            # Server is busy
            if len(queue) < b:
                queue.append((ti, di, idx))
            else:
                results[idx] = -1
            i += 1
    else:
        # Server is busy and no more queries, process queue
        if queue:
            tiq, diq, idxq = queue.pop(0)
            server_free += diq
            results[idxq] = server_free
        else:
            break

print(' '.join(map(str, results)))
