import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    q = int(next(it))

    results = []

    for _ in range(q):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Count frequency of each value
        freq = {}
        for val in a:
            freq[val] = freq.get(val, 0) + 1

        # Count how many unique values are out of order
        out_of_order = set()
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                # a[i] is greater than the next value, so it's out of order
                out_of_order.add(a[i])

        # Also check if the last value is greater than any previous value
        # (this might be needed if the sequence ends with a larger value)
        for val in freq:
            if val in out_of_order:
                continue
            # Check if val appears before any smaller value
            for i in range(n):
                if a[i] == val:
                    # Check if there's a smaller value after this position
                    for j in range(i + 1, n):
                        if a[j] < val:
                            out_of_order.add(val)
                            break

        results.append(str(len(out_of_order)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
