import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    q = int(next(it))

    results = []

    for _ in range(q):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # If already sorted, answer is 0
        is_sorted = True
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                is_sorted = False
                break
        if is_sorted:
            results.append("0")
            continue

        # Strategy: count how many different values cause an inversion
        out_of_order = set()
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                out_of_order.add(a[i])

        # If the sequence ends with a value that's smaller than the previous
        # it might cause an additional inversion
        for i in range(n - 2, -1, -1):
            if a[i + 1] < a[i]:
                out_of_order.add(a[i + 1])

        results.append(str(len(out_of_order)))

    sys.stdout.write("\n".join(results))

