def solve():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v, c = input().split()
        u = int(u) - 1  # 0-indexed
        v = int(v) - 1
        edges.append((u, v, c))

    # Gaussian elimination over GF(2)
    def solve_system(target_color):
        # Build matrix: rows for edges, columns for vertices
        # Each row: (row_number, mask)
        # mask has bits for vertices; if bit i is 1, vertex i is in equation
        # The last bit represents the constant term
        rows = []
        for i, (u, v, c) in enumerate(edges):
            # Equation: x_u + x_v = target (1 if we want to flip, 0 otherwise)
            # target: 1 if we want to flip this edge, 0 otherwise
            target = 1 if (c == 'R' and target_color == 'B') or (c == 'B' and target_color == 'R') else 0
            mask = (1 << u) | (1 << v)
            rows.append((i, mask, target))

        # Perform Gaussian elimination
        rank = 0
        for col in range(n):
            # Find pivot
            pivot_row = -1
            for r, _, _ in rows:
                if (rows[r][1] >> col) & 1:
                    pivot_row = r
                    break

            if pivot_row == -1:
                continue  # no pivot in this column

            # Swap to top
            rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]

            # Eliminate this column from other rows
            for r in range(n):
                if r != rank and (rows[r][1] >> col) & 1:
                    rows[r] = (rows[r][0], rows[r][1] ^ rows[rank][1], rows[r][2] ^ rows[rank][2])

            rank += 1

        # Check consistency
        solution = [0] * n
        for r in range(rank):
            # Equation: sum of bits * x = constant
            # Find the pivot column
            pivot_col = -1
            for c in range(n):
                if (rows[r][1] >> c) & 1:
                    pivot_col = c
                    break

            if pivot_col == -1:
                continue  # shouldn't happen

            # Solve for pivot variable
            solution[pivot_col] = rows[r][2]

        # Check if all equations are satisfied
        for r in range(rank):
            lhs = 0
            for c in range(n):
                if (rows[r][1] >> c) & 1:
                    lhs ^= solution[c]
            if lhs != rows[r][2]:
                return None  # inconsistent

        return solution

    # Try both target colors
    best = None
    for target_color in ['R', 'B']:
        solution = solve_system(target_color)
        if solution is not None:
            flips = sum(solution)
            if best is None or flips < best[0]:
                best = (flips, [i + 1 for i, val in enumerate(solution) if val])

    if best is not None:
        print(best[0])
        print(' '.join(map(str, best[1])))
    else:
        print(-1)

