def solve(s):
    n = len(s)

    # Precompute Grundy numbers for all substrings
    grundy = [[0] * n for _ in range(n)]

    # Base case: length 1
    for i in range(n):
        grundy[i][i] = 0

    # For strings of length > 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            reachable = set()

            # Check each possible position to cut
            for k in range(i, j + 1):
                # Check if position k can be cut (0-indexed from i to j)
                # Need symmetric characters around position k
                can_cut = True
                for l in range(1, min(k - i, j - k) + 1):
                    if s[i + k - i - l] != s[i + k - i + l]:
                        can_cut = False
                        break

                if can_cut:
                    # Cut at position k, resulting in three substrings
                    # Left: [i, k-1], Right: [k+1, j]
                    left = grundy[i][k - 1]
                    right = grundy[k + 1][j]
                    # Middle is just a single character with Grundy number 0
                    # Resulting Grundy number is left ^ right
                    reachable.add(left ^ right)

            # Compute Grundy number using mex
            mex = 0
            while mex in reachable:
                mex += 1
            grundy[i][j] = mex

    # Starting position: entire string [0, n-1]
    if grundy[0][n-1] == 0:
        return "Second"
    else:
        # Find the minimal winning move
        for i in range(n):
            # Check if cutting at position i leads to a losing position
            # Resulting Grundy number is grundy[0][i-1] ^ grundy[i+1][n-1]
            if i == 0:
                result = grundy[i+1][n-1]
            elif i == n-1:
                result = grundy[0][i-1]
            else:
                result = grundy[0][i-1] ^ grundy[i+1][n-1]

            if result == 0:
                return f"First\n{i + 1}"
        return "Second"

