def count_intervals(n, a, b):
    """Count the number of intervals [l, r] where max(a[l..r]) == min(b[l..r])."""

    # Find ranges where a[i] is the maximum in a
    left_max = [0] * n
    right_max = [0] * n

    # nearest greater or equal to the left
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        if stack:
            left_max[i] = stack[-1] + 1
        else:
            left_max[i] = 0
        stack.append(i)

    # nearest greater to the right
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and a[stack[-1]] <= a[i]:
            stack.pop()
        if stack:
            right_max[i] = stack[-1] - 1
        else:
            right_max[i] = n - 1
        stack.append(i)

    # Find ranges where b[i] is the minimum in b
    left_min = [0] * n
    right_min = [0] * n

    # nearest smaller or equal to the left
    stack = []
    for i in range(n):
        while stack and b[stack[-1]] > b[i]:
            stack.pop()
        if stack:
            left_min[i] = stack[-1] + 1
        else:
            left_min[i] = 0
        stack.append(i)

    # nearest smaller to the right
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and b[stack[-1]] >= b[i]:
            stack.pop()
        if stack:
            right_min[i] = stack[-1] - 1
        else:
            right_min[i] = n - 1
        stack.append(i)

    # Count intervals
    count = 0
    for i in range(n):
        # Range where a[i] is max in a: [left_max[i], right_max[i]]
        # Range where b[i] is min in b: [left_min[i], right_min[i]]
        # Intersection range: [max(left_max[i], left_min[i]), min(right_max[i], right_min[i])]

        start = max(left_max[i], left_min[i])
        end = min(right_max[i], right_min[i])

        if start <= end:
            count += end - start + 1

