# vertex that has capacity
for v in range(n):
    if degree[v] == 0:
        # Connect to the first vertex with degree > 0 that doesn't have v
        # in its XOR sum and can have a neighbor
        for w in range(n):
            if w != v and degree[w] > 0 and (s[w] & (1 << v)) == 0 and (s[v] & (1 << w)) == 0:
                adj = [[] for _ in range(n)]
                adj[v].append(w)
                adj[w].append(v)

                degree[v] = 1
                degree[w] -= 1
                s[v] ^= w
                s[w] ^= v

                break

# For vertices with remaining capacity, find each other
for i in range(n):
