prices = list(map(int, input().split()))

# We can only hold one share at a time
# Buy when we see a price that is a local minimum
# Sell when we see a price that is a local maximum

# Find all local minima and maxima
local_minima = []
local_maxima = []

for i in range(N):
    # Check if it's a local minimum
    if i == 0 or i == N - 1:
        is_min = False
    else:
        is_min = prices[i] < prices[i-1] and prices[i] < prices[i+1]
    if is_min:
        local_minima.append(i)

    # Check if it's a local maximum
    if i == 0 or i == N - 1:
        is_max = False
    else:
        is_max = prices[i] > prices[i-1] and prices[i] > prices[i+1]
    if is_max:
        local_maxima.append(i)

# Buy at local minima, sell at local maxima
profit = 0
buy_index = -1

for i in range(N):
    if buy_index == -1 and i in local_minima:
        buy_index = i
        profit -= prices[i]
    elif buy_index != -1 and i in local_maxima:
        profit += prices[i]
        buy_index = -1

print(profit)
