import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    a = []
    for _ in range(n):
        a.append(int(data[idx])); idx += 1

    b = []
    for _ in range(m):
        b.append(int(data[idx])); idx += 1

    max_correct = max(a)
    min_wrong = min(b)

    if max_correct >= min_wrong:
        print(-1)
        return

    # Find correct solutions that can pass with extra time
    valid_ai = []
    for ai in a:
        if 2 * ai <= max_correct:
            valid_ai.append(ai)

    if not valid_ai:
        print(-1)
        return

    # Find the smallest 2*ai that is >= max_correct
    # We need v = max(max_correct, 2*ai) for some ai
    # Since max_correct >= ai, max(max_correct, 2*ai) = max(max_correct, 2*ai)
    # We need v < min_wrong

    # The minimum v that satisfies all is the minimum of max(max_correct, 2*ai)
    # where ai is such that 2*ai <= max_correct

    min_v = float('inf')
    for ai in valid_ai:
        v_candidate = max(max_correct, 2 * ai)
        if v_candidate < min_wrong:
            min_v = min(min_v, v_candidate)

    if min_v == float('inf'):
        print(-1)
    else:
        print(min_v)

if __name__ == "__main__":
    solve()
"}

