    names = []
    for _ in range(n):
        name = sys.stdin.readline().strip()
        names.append(name)

    # dp[start][end] = maximum total length of a chain that starts with 'start' and ends with 'end'
    dp = {}

    for name in names:
        s = name[0]
        e = name[-1]
        l = len(name)

        # Try to extend existing chains
        for prev_end, chain_length in dp.items():
            if prev_end == s:
                dp[(s, e)] = max(dp.get((s, e), 0), chain_length + l)

        # Start a new chain with this name
        dp[(s, e)] = max(dp.get((s, e), 0), l)

    # Find the maximum chain that forms a loop (start == end)
    max_length = 0
    for start, end in dp:
        if start == end:
            max_length = max(max_length, dp[(start, end)])

    print(max_length)

if __name__ == "__main__":
