import sys

def is_valid_username(s):
    """Check if a string is a valid username."""
    if not 1 <= len(s) <= 16:
        return False
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    return all(c in allowed for c in s)

def is_valid_hostname(s):
    """Check if a string is a valid hostname."""
    if not 1 <= len(s) <= 32:
        return False
    parts = s.split('.')
    if len(parts) == 0:
        return False
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    for part in parts:
        if not 1 <= len(part) <= 16:
            return False
        if not all(c in allowed for c in part):
            return False
    return True

def is_valid_resource(s):
    """Check if a string is a valid resource."""
    if not 1 <= len(s) <= 16:
        return False
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    return all(c in allowed for c in s)

