if not line:
    print("NO")
    sys.exit()

# Check if there's an optional resource at the end
if line.endswith('/'):
    # Check if it's the last character
    if len(line) == 1 or line[-2] != '@':
        print("NO")
        sys.exit()
    resource_part = line.split('/')[-1]
    if not is_valid_resource(resource_part):
        print("NO")
        sys.exit()
    line = line[:line.rfind('/')]

# Split into username and hostname parts
if '@' not in line:
    print("NO")
    sys.exit()

username_part, hostname_part = line.split('@', 1)

if not is_valid_username(username_part):
    print("NO")
    sys.exit()

if not is_valid_hostname(hostname_part):
