import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    t = int(data[0])

    for i in range(1, t + 1):
        cards = data[i].strip()

        # For each test case, check all factor pairs
        factor_pairs = [(1, 12), (2, 6), (3, 4), (4, 3), (6, 2), (12, 1)]

        # Check which pairs result in a win
        valid = []

        for a, b in factor_pairs:
            # Check each column
            found = False

            for col in range(b):
                all_x = True
                for row in range(a):
                    pos = col + row * b
                    if cards[pos] != 'X':
                        all_x = False
                        break

                if all_x:
                    found = True
                    break

            if found:
                valid.append(f"{a}x{b}")

        # Output result
        if valid:
            print(f"{len(valid)} {' '.join(valid)} ")
        else:
            print("0 ")

if __name__ == "__main__":
    solve()
