import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Initialize BIT
    max_val = n  # Since elements are between 1 and n
    bit = [0] * (max_val + 2)  # 1-indexed

    def update(pos, delta):
        """Update the BIT at position pos by delta."""
        while pos <= max_val:
            bit[pos] += delta
            pos += pos & -pos

    def query(pos):
        """Query the prefix sum up to position pos."""
        res = 0
        while pos > 0:
            res += bit[pos]
            pos -= pos & -pos
        return res

    def find_kth(k):
        """Find the k-th order statistic."""
        # Binary search to find the smallest position where prefix sum >= k
        low, high = 1, max_val
        while low < high:
            mid = (low + high) // 2
            if query(mid) >= k:
                high = mid
            else:
                low = mid + 1
        return low

    # Process initial elements
    for _ in range(n):
        val = int(next(it))
        update(val, 1)

    # Process queries
    for _ in range(q):
        k = int(next(it))
        if k > 0:
            # Insert k
            update(k, 1)
        else:
            # Remove k-th order statistic
            k_abs = -k
            pos = find_kth(k_abs)
            update(pos, -1)

    # Find any remaining element
    total = query(max_val)
    if total == 0:
        print(0)
    else:
        # Find the smallest element with non-zero count
        for i in range(1, max_val + 1):
            if query(i) > query(i - 1):
                print(i)
                return

if __name__ == "__main__":
    solve()
"}

