import sys

def solve_binary_maximize(binary_str):
    """
    Find the maximum binary number after deleting exactly one digit.
    """
    # Find the first position where we can delete a '0' and still have at least one '1' after it
    for i in range(len(binary_str)):
        if binary_str[i] == '0':
            # Check if there's at least one '1' after this position
            if '1' in binary_str[i+1:]:
                return binary_str[:i] + binary_str[i+1:]

    # If no '0' found, delete the last '1'
    return binary_str[:-1]

