    """Check if a string is a valid username."""
    if len(s) < 1 or len(s) > 16:
        return False
    if not re.match(r'^[a-zA-Z0-9_]+$', s):
        return False
    return True

def is_valid_hostname(s):
    """Check if a string is a valid hostname."""
    if len(s) < 1 or len(s) > 32:
        return False
    # Split by periods
    parts = s.split('.')
    for part in parts:
        if len(part) < 1 or len(part) > 16:
            return False
        if not re.match(r'^[a-zA-Z0-9_]+$', part):
            return False
    return True

def is_valid_resource(s):
    """Check if a string is a valid resource."""
    if len(s) < 1 or len(s) > 16:
        return False
    if not re.match(r'^[a-zA-Z0-9_]+$', s):
        return False
    return True

# Read input
input_str = input().strip()

# Check if it's a valid Jabber ID
if '@' not in input_str:
    print("NO")
    exit()

# Split into username and the rest
username_part, rest = input_str.split('@', 1)

# Check username
if not is_valid_username(username_part):
    print("NO")
    exit()

# Check if there's a resource
if '/' in rest:
    # Split into hostname and resource
    hostname_part, resource_part = rest.split('/', 1)

    # Check resource
    if not is_valid_resource(resource_part):
        print("NO")
        exit()

    # Check hostname
    if not is_valid_hostname(hostname_part):
        print("NO")
        exit()
else:
    # No resource, just check hostname
    if not is_valid_hostname(rest):
        print("NO")
        exit()

print("YES")
"}

