import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    d = int(data[1])

    messages = []
    idx = 2
    for _ in range(n):
        sender = data[idx]
        receiver = data[idx+1]
        time = int(data[idx+2])
        messages.append((sender, receiver, time))
        idx += 3

    friends = set()

    for i, (sender, receiver, time) in enumerate(messages):
        # Check if there's a previous message from receiver to sender within [time, time+d]
        for j in range(i):
            prev_sender, prev_receiver, prev_time = messages[j]
            if prev_sender == receiver and prev_receiver == sender:
                if 0 < time - prev_time <= d:
                    friends.add((sender, receiver))
                    friends.add((receiver, sender))

    print(len(friends))
    for pair in sorted(friends):
        print(pair[0], pair[1])

if __name__ == "__main__":
    solve()
"}

