def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Use a dictionary for frequencies (can handle any integer value)
    freq = {}

    # Read initial elements
    for _ in range(n):
        val = int(next(it))
        if val in freq:
            freq[val] += 1
        else:
            freq[val] = 1

    # Read queries
    for _ in range(q):
        k = int(next(it))
        if k > 0:
            # Add k to the multiset
            if k in freq:
                freq[k] += 1
            else:
                freq[k] = 1
        else:
            # Remove the |k|-th order statistic
            target_k = -k
            # Find the smallest i such that sum(freq[1..i]) >= target_k
            # We need to iterate through all keys in sorted order
            sorted_keys = sorted(freq.keys())
            i = 1
            sum_freq = 0
            found = False

            for key in sorted_keys:
                if sum_freq + freq[key] >= target_k:
                    # Found the element
                    freq[key] -= 1
                    if freq[key] == 0:
                        del freq[key]
                    found = True
                    break
                sum_freq += freq[key]

            if not found:
                # This shouldn't happen because the problem guarantees it
                pass

    # Check if multiset is empty
    if not freq:
        print(0)
    else:
        # Print any element in the multiset
        for key in freq:
            print(key)
            return

