import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Build graph
    graph = defaultdict(list)
    edges = []

    idx = 2
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx+1])
        graph[a].append(b)
        graph[b].append(a)
        edges.append((a, b))
        idx += 2

    # Find cycles using BFS
    visited = set()
    cycles = []

    def bfs_cycle(start):
        parent = {start: -1}
        depth = {start: 1}
        path = [start]

        while path:
            node = path.pop()
            for neighbor in graph[node]:
                if depth.get(neighbor, 0) == 0:
                    parent[neighbor] = node
                    depth[neighbor] = depth[node] + 1
                    path.append(neighbor)
                elif parent[node] != neighbor and parent[neighbor] != node:
                    # Found a cycle
                    cycle = depth[node] - depth[neighbor] + 1
                    cycles.append(cycle)
                    # But this might count each cycle twice, so we need to be careful
                    # We just add the cycle length to the list multiple times


    for node in range(1, n+1):
        if node not in visited:
            bfs_cycle(node)
            visited.update({n for n in range(1, n+1) if depth.get(n, 0) > 0})

    # Calculate answer
    answer = 0
    for cycle in cycles:
        if cycle % 2 == 1:
            answer += (cycle + 1) // 2

    print(answer)

if __name__ == "__main__":
    solve()
