import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    a = []
    for _ in range(n):
        a.append(int(next(it)))

    # Create a map from value to first occurrence index
    value_to_first_idx = {}
    for idx, val in enumerate(a):
        if val not in value_to_first_idx:
            value_to_first_idx[val] = idx

    out_lines = []
    for _ in range(m):
        li = int(next(it)) - 1  # Convert to 0-indexed
        ri = int(next(it)) - 1
        xi = int(next(it))

        first_occurrence = value_to_first_idx.get(xi, -1)

        if first_occurrence < li or first_occurrence > ri:
            # All elements in [li, ri] are not xi
            if a[li] != xi:
                out_lines.append(str(li + 1))  # Convert back to 1-indexed
            elif a[ri] != xi:
                out_lines.append(str(ri + 1))
            else:
                out_lines.append("-1")
        else:
            # first_occurrence is within [li, ri]
            if a[li] != xi:
                out_lines.append(str(li + 1))
            elif a[ri] != xi:
                out_lines.append(str(ri + 1))
            else:
                out_lines.append("-1")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

