    non_negative = 0
    non_positive = 0
    for i in range(n - 1):
        diff = b[i+1] - b[i]
        if diff >= 0:
            non_negative += 1
        else:
            non_positive += 1

    required = (n - 1) // 2

    # If we have enough of each, we're done
    if non_negative >= required and non_positive >= required:
        print(' '.join(map(str, b)))
