    # Try flipping signs in a wave pattern
    # Flip every other sign starting with the first element
    flipped = [False] * n
    for i in range(n):
        if i % 2 == 0:
            flipped[i] = True

    b = [a[i] if not flipped[i] else -a[i] for i in range(n)]

