import sys

def is_square_formed(rectangles):
    # Find bounding box
    min_x = min(r[0] for r in rectangles)
    max_x = max(r[2] for r in rectangles)
    min_y = min(r[1] for r in rectangles)
    max_y = max(r[3] for r in rectangles)

    # Check if bounding box is a square
    if (max_x - min_x) != (max_y - min_y):
        return False

    # Check if all points in the square are covered
    side = max_x - min_x
    for x in range(min_x, max_x):
        for y in range(min_y, max_y):
            covered = False
            for (x1, y1, x2, y2) in rectangles:
                if x1 <= x < x2 and y1 <= y < y2:
                    covered = True
                    break
            if not covered:
                return False

    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    rectangles = []
    idx = 1
    for _ in range(n):
