MOD = 10**9 + 7

n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(input().strip())

# dp[i][j] = number of paths to (i, j)
dp = [[0] * (m + 1) for _ in range(n + 1)]
dp[1][1] = 1

# Precompute for each cell (i, j):
# - count of consecutive rocks to the right starting at (i, j)
right_count = [[0] * (m + 1) for _ in range(n + 1)]
# - count of consecutive rocks below starting at (i, j)
down_count = [[0] * (m + 1) for _ in range(n + 1)]

for i in range(1, n + 1):
    for j in range(1, m + 1):
        # Count consecutive rocks to the right
        if grid[i-1][j-1] == 'R':
            k = 1
            jj = j
            while jj < m and grid[i-1][jj] == 'R':
                jj += 1
            right_count[i][j] = jj - j
        else:
            right_count[i][j] = 0

        # Count consecutive rocks below
        if grid[i-1][j-1] == 'R':
            k = 1
            ii = i
            while ii < n and grid[ii][j-1] == 'R':
                ii += 1
            down_count[i][j] = ii - i
        else:
            down_count[i][j] = 0

# Fill DP table
for i in range(1, n + 1):
    for j in range(1, m + 1):
        if i == 1 and j == 1:
            continue

        # Check if we can come from above (i-1, j)
        from_above = False
        if grid[i-2][j-1] == 'R':
            # (i-1, j) has a rock
            if right_count[i-1][j] < m - j:
                # The rock chain doesn't extend all the way to the right edge
                from_above = True
        else:
            # (i-1, j) is empty, we can move down
            from_above = True

        if from_above:
            dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD

        # Check if we can come from the left (i, j-1)
        from_left = False
        if grid[i-1][j-2] == 'R':
            # (i, j-1) has a rock
            if down_count[i][j-1] < n - i:
                # The rock chain doesn't extend all the way down
                from_left = True
        else:
            # (i, j-1) is empty, we can move right
            from_left = True

        if from_left:
            dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

print(dp[n][m])
