    n = len(A)
    m = len(A[0])
    rank = 0
    for col in range(m):
        pivot = -1
        for row in range(rank, n):
            if A[row][col] == 1:
                pivot = row
                break
        if pivot == -1:
            continue
        # Swap pivot row with rank row
        A[rank], A[pivot] = A[pivot], A[rank]
        b[rank], b[pivot] = b[pivot], b[rank]
