    u = int(u) - 1  # 0-indexed
    v = int(v) - 1
    edges.append((u, v, c))

# Build system for all edges red
A = []
b = []
for i, (u, v, c) in enumerate(edges):
    row = [0] * n
    row[u] = 1
    row[v] = 1
    A.append(row)
    if c == 'R':
        b.append(0)
    else:
        b.append(1)

# Solve using Gaussian elimination over GF(2)
def solve_system(A, b):
    n_rows = len(A)
    n_cols = len(A[0])
    rank = 0
    for col in range(n_cols):
        pivot = -1
        for row in range(rank, n_rows):
            if A[row][col] == 1:
                pivot = row
                break
        if pivot == -1:
            continue
        # Swap pivot row with rank row
        A[rank], A[pivot] = A[pivot], A[rank]
        b[rank], b[pivot] = b[pivot], b[rank]
        # Eliminate
        for row in range(n_rows):
            if row != rank and A[row][col] == 1:
                for c in range(col, n_cols):
                    A[row][c] ^= A[rank][c]
                b[row] ^= b[rank]
        rank += 1
    # Check consistency
    for row in range(rank, n_rows):
        if b[row] == 1:
            return None
    # Back substitution
    solution = [0] * n_cols
    for row in range(rank):
        val = b[row]
        for col in range(n_cols):
            if A[row][col] == 1:
                val ^= solution[col]
        solution[col] = val
    return solution

solution_red = solve_system(A, b)

# Build system for all edges blue
A_blue = []
b_blue = []
for i, (u, v, c) in enumerate(edges):
    row = [0] * n
    row[u] = 1
    row[v] = 1
    A_blue.append(row)
    if c == 'B':
        b_blue.append(0)
    else:
        b_blue.append(1)

solution_blue = solve_system(A_blue, b_blue)

# Find minimum solution
min_count = float('inf')
min_solution = None

if solution_red is not None:
    cnt = sum(solution_red)
    if cnt < min_count:
        min_count = cnt
        min_solution = solution_red

if solution_blue is not None:
    cnt = sum(solution_blue)
    if cnt < min_count:
        min_count = cnt
        min_solution = solution_blue

if min_count == float('inf'):
    print(-1)
else:
    print(min_count)
    for i in range(n):
        if min_solution[i] == 1:
            print(i + 1, end=' ')
    print()

