def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, m, k = map(int, input().split())

        # dp[n][m][k] = minimum cost to get k squares from n x m bar
        dp = [[[float('inf')] * (k + 1) for _ in range(m + 1)] for __ in range(n + 1)]

        # Base cases: need 0 or all squares
        for i in range(n + 1):
            for j in range(m + 1):
                dp[i][j][0] = 0
                dp[i][j][i * j] = 0

        # Fill dp table
        for size in range(1, n * m + 1):
            for i in range(n + 1):
                for j in range(m + 1):
                    if i * j == size:
                        # Consider all possible ways to break this bar
                        # Horizontal breaks
                        for k1 in range(1, size):
                            for h in range(1, i):
                                dp[i][j][size] = min(
                                    dp[i][j][size],
                                    h * h + dp[h][j][k1] + dp[i - h][j][size - k1]
                                )
                        # Vertical breaks
                        for k1 in range(1, size):
                            for v in range(1, j):
                                dp[i][j][size] = min(
                                    dp[i][j][size],
                                    v * v + dp[i][v][k1] + dp[i][j - v][size - k1]
                                )

        results.append(dp[n][m][k])

    for res in results:
        print(res)

