def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, m, k = map(int, input().split())

        # dp[n][m][k] = minimum cost to get k squares from n x m bar
        max_k = n * m
        dp = [[[float('inf')] * (max_k + 1) for _ in range(m + 1)] for __ in range(n + 1)]

        # Base cases: need 0 or all squares
        for i in range(n + 1):
            for j in range(m + 1):
                dp[i][j][0] = 0
                dp[i][j][i * j] = 0

        # Fill dp table
        # Loop over all possible n, m, k combinations
        for i in range(n + 1):
            for j in range(m + 1):
                # We need to consider k from 1 to total number of squares in i x j bar
                # but only if k <= max_k
                for k in range(1, min(i * j, max_k) + 1):

                    # Consider all possible horizontal breaks (break along i dimension, length = j)
                    for h in range(1, i):
                        for k1 in range(1, min(k, h * j) + 1):
                            k2 = k - k1
                            if k1 <= h * j and k2 <= (i - h) * j:
                                # Cost is j * j (break length = j, so cost = j^2 = j * j)
                                dp[i][j][k] = min(dp[i][j][k], j * j + dp[h][j][k1] + dp[i - h][j][k2])

                    # Consider all possible vertical breaks (break along j dimension, length = i)
                    for v in range(1, j):
                        for k1 in range(1, min(k, i * v) + 1):
                            k2 = k - k1
                            if k1 <= i * v and k2 <= i * (j - v):
                                # Cost is i * i (break length = i, so cost = i^2 = i * i)
                                dp[i][j][k] = min(dp[i][j][k], i * i + dp[i][v][k1] + dp[i][j - v][k2])

        results.append(dp[n][m][k])

    for res in results:
        print(res)

