def is_subsequence(a, b):
    """Check if a is a subsequence of b"""
    i = 0  # pointer for a
    j = 0  # pointer for b
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            i += 1
        j += 1
    return i == len(a)

def solve():
    s = input().strip()
    t = input().strip()

    # Check if s is a subsequence of t at all
    if not is_subsequence(s, t):
        print(0)
        return

    # Precompute left array: left[i] = True if s is subsequence of t[:i]
    left = [False] * (len(t) + 1)
    left[0] = True

    for i in range(len(t)):
        left[i+1] = left[i] or is_subsequence(s, t[:i+1])

    # Precompute right array: right[i] = True if s is subsequence of t[i:]
    right = [False] * (len(t) + 1)
    right[len(t)] = True

    for i in range(len(t)-1, -1, -1):
        right[i] = right[i+1] or is_subsequence(s, t[i:])

    # Count valid splits
    count = 0
    for i in range(1, len(t)):
        if left[i] and right[i]:
            count += 1

    print(count)

solve()
