def pow_mod(base, exp):
    """Compute base^exp mod MOD efficiently."""
    result = 1
    base = base % MOD
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exp //= 2
    return result

def solve():
    n, m, k = map(int, input().split())

    if n == 1 and m == 1:
        if k == -1:
            print(1)
        else:
            print(0)
    elif n == 1 or m == 1:
        if k == 1:
            print(1)
        else:
            print(0)
    else:
        # n > 1 and m > 1
        if k == 1:
            power = (n - 1) * (m - 1)
            print(pow_mod(2, power))
        else:  # k == -1
            power = (n - 1) * (m - 1)
            # Check if (m - n) is even
            if (m - n) % 2 == 0:
                print(pow_mod(2, power))
            else:
                print(0)

solve()
