from collections import defaultdict
import sys

def kmp_failure(pattern):
    """Compute failure function for KMP algorithm"""
    n = len(pattern)
    fail = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and pattern[i] != pattern[j]:
            j = fail[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            fail[i] = j
        else:
            fail[i] = 0
    return fail

def kmp_count(text, pattern):
    """Count occurrences of pattern in text using KMP"""
    if not pattern:
        return 0
    n, m = len(text), len(pattern)
    fail = kmp_failure(pattern)
    j = 0
    count = 0

    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = fail[j - 1]
        if text[i] == pattern[j]:
            j += 1
            if j == m:
                count += 1
                j = fail[j - 1]
    return count

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    t = data[0]
    n = int(data[1])
    strings = data[2:2+n]

    result = 0

    # Group by concatenated strings
    count_map = defaultdict(int)

    for i in range(n):
        for j in range(n):
            pattern = strings[i] + strings[j]
            # Early termination if pattern is too long
            if len(pattern) > len(t):
                continue

            # Count occurrences in t
            occurrences = kmp_count(t, pattern)
            count_map[pattern] += occurrences

    # Sum all counts
    result = sum(count_map.values())

    print(result)

if __name__ == "__main__":
    solve()
"}

